    ('0399dc65-9d41-56cc-a0c0-e68818658988'::uuid, 'Grandeurs et mesures'),
    ('4d26d6b1-b65f-5c4a-86c8-4621f7358b26'::uuid, 'Grandeurs et mesures'),
