    ('7f62a1dc-4139-53b3-a43f-64c4ccef04c9'::uuid, '70d2a7a9-1223-59c8-b538-8a0914dce48f'::uuid, 'Que valent les angles d’un triangle isocèle rectangle ?', 'mcq', '["90°, 45° et 45°","90°, 60° et 30°","60°, 60° et 60°","90°, 50° et 40°"]'::jsonb, 0, 'Il cumule l’angle droit et les deux côtés égaux.', 6),
