    ('cebd94a8-a08d-57bf-a88e-e0732425e43d'::uuid, '70d2a7a9-1223-59c8-b538-8a0914dce48f'::uuid, 'Tout triangle isocèle est équilatéral.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’inverse : tout équilatéral est isocèle.', 8),
    ('4e6f5418-2ca1-54ea-863a-0029f2dcdfb1'::uuid, '91480373-1232-5422-8263-17c167215d7d'::uuid, 'Quelle est la définition du symétrique A’ de A par rapport à une droite (d) ?', 'mcq', '["(d) est la médiatrice de [AA’]","(d) passe par A","(d) est parallèle à [AA’]","A’ est le milieu de (d)"]'::jsonb, 0, 'C’est la définition à retenir.', 1),
    ('fd9d2dad-8eed-5744-8f48-e2091bf425ab'::uuid, '91480373-1232-5422-8263-17c167215d7d'::uuid, 'Quel est le symétrique d’un point situé sur l’axe ?', 'mcq', '["Lui-même","Un point de l’autre côté","Le milieu de l’axe","Il n’en a pas"]'::jsonb, 0, 'Sa distance à l’axe est nulle.', 2),
    ('b3e594c8-5f72-5221-bb86-80c0a52d49d1'::uuid, '91480373-1232-5422-8263-17c167215d7d'::uuid, 'Que conserve la symétrie axiale ?', 'mcq', '["Les longueurs, les angles et les aires","Seulement les longueurs","Seulement les angles","Rien"]'::jsonb, 0, 'Elle conserve aussi l’alignement et le parallélisme.', 3),
    ('41070c92-5691-5296-9b55-fb26d61c2cad'::uuid, '91480373-1232-5422-8263-17c167215d7d'::uuid, 'Combien d’axes de symétrie a un carré ?', 'mcq', '["4","2","1","Une infinité"]'::jsonb, 0, 'Le rectangle n’en a que 2.', 4),
    ('ad8025d5-2b35-5468-9ab3-c45716f84a6c'::uuid, '91480373-1232-5422-8263-17c167215d7d'::uuid, 'Combien d’axes de symétrie a un parallélogramme quelconque ?', 'mcq', '["Aucun","Un","Deux","Quatre"]'::jsonb, 0, 'C’est le piège classique du chapitre.', 5),
    ('87a37a22-91f1-5d2e-a85a-c206b21c4c72'::uuid, '91480373-1232-5422-8263-17c167215d7d'::uuid, 'Combien d’axes de symétrie a un cercle ?', 'mcq', '["Une infinité","Un","Deux","Quatre"]'::jsonb, 0, 'Tous ses diamètres sont des axes.', 6),
    ('1a75bd77-5d21-59a7-bbf8-697c7954f860'::uuid, '91480373-1232-5422-8263-17c167215d7d'::uuid, 'Qu’est-ce que la symétrie axiale modifie ?', 'mcq', '["Le sens de lecture","Les longueurs","Les angles","Les aires"]'::jsonb, 0, 'C’est la seule chose qu’elle change.', 7),
    ('a04c9a93-0a6d-54cb-a2ee-6b06b197c9f5'::uuid, '91480373-1232-5422-8263-17c167215d7d'::uuid, 'Une figure et son symétrique sont superposables.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elles ont la même forme et la même taille.', 8),
    ('f7e008a4-9f19-5a35-bf8d-a7bc5bde1e2c'::uuid, '047b3724-6a72-5a29-91f1-24f6750dfbf5'::uuid, 'Combien d’arêtes a un cube ?', 'mcq', '["12","6","8","4"]'::jsonb, 0, 'Il a 6 faces et 8 sommets.', 1),
    ('b6c41eea-bc67-5d1f-8c87-4a03ed9ebce2'::uuid, '047b3724-6a72-5a29-91f1-24f6750dfbf5'::uuid, 'Quelle est la formule du volume d’un pavé droit ?', 'mcq', '["L × l × h","L × l","2 × (L + l + h)","L + l + h"]'::jsonb, 0, 'Le résultat s’exprime en unités cubes.', 2),
    ('4343ec40-f40a-50b1-9033-4b8dfaca0f03'::uuid, '047b3724-6a72-5a29-91f1-24f6750dfbf5'::uuid, 'À quoi correspond 1 litre ?', 'mcq', '["1 dm³","1 cm³","1 m³","1 mm³"]'::jsonb, 0, 'Et 1 mL vaut 1 cm³.', 3),
    ('874f5061-0240-531a-a16e-9d00ae05a48a'::uuid, '047b3724-6a72-5a29-91f1-24f6750dfbf5'::uuid, 'Combien de cm³ dans 1 dm³ ?', 'mcq', '["1 000 cm³","100 cm³","10 cm³","1 000 000 cm³"]'::jsonb, 0, 'Chaque rang vaut 1 000 fois le suivant.', 4),
    ('832be5f7-9868-5c52-acbc-86afc24fb7d8'::uuid, '047b3724-6a72-5a29-91f1-24f6750dfbf5'::uuid, 'Qu’est-ce qu’un patron ?', 'mcq', '["Le dessin à plat qui, plié, redonne le solide","La vue de face du solide","Le volume du solide","Le contour d’une face"]'::jsonb, 0, 'Le cube en a onze différents.', 5),
