    ('687bf12e-6a00-5dd5-8f9f-0b3a54ee9907'::uuid, '047b3724-6a72-5a29-91f1-24f6750dfbf5'::uuid, 'Comment représente-t-on les arêtes cachées en perspective cavalière ?', 'mcq', '["En pointillés","En traits gras","En rouge","On ne les dessine pas"]'::jsonb, 0, 'Les faces de face sont en vraie grandeur.', 7),
