    ('28694b86-d873-537a-b415-bdfe7c56489c'::uuid, '871bb1a6-ec94-5ed9-974d-28d0b3b30b82'::uuid, 'Que signifie « deux grandeurs proportionnelles » ?', 'mcq', '["On passe de l’une à l’autre en multipliant toujours par le même nombre","Elles augmentent toutes les deux","Elles sont égales","Leur somme est constante"]'::jsonb, 0, 'Ce nombre est le coefficient de proportionnalité.', 1),
    ('9a1c09b9-3955-5785-91c4-826556c728d7'::uuid, '871bb1a6-ec94-5ed9-974d-28d0b3b30b82'::uuid, 'Des pommes coûtent 3 € le kilo. Combien coûtent 5 kg ?', 'mcq', '["15 €","8 €","12 €","5 €"]'::jsonb, 0, 'On multiplie par le coefficient 3.', 2),
    ('98c4367e-e585-5480-8dc5-b1158f83a7cf'::uuid, '871bb1a6-ec94-5ed9-974d-28d0b3b30b82'::uuid, 'Laquelle de ces situations n’est PAS proportionnelle ?', 'mcq', '["L’âge et la taille d’une personne","Le prix et la quantité à prix unitaire fixe","La distance et la durée à vitesse constante","Le périmètre d’un carré et son côté"]'::jsonb, 0, 'La taille n’augmente pas au même rythme que l’âge.', 3),
    ('1820ec63-318f-58ea-9c84-be28a49ee36b'::uuid, '871bb1a6-ec94-5ed9-974d-28d0b3b30b82'::uuid, 'Comment trouve-t-on le coefficient de proportionnalité ?', 'mcq', '["En divisant une valeur de la 2e ligne par celle de la 1re","En additionnant les deux lignes","En multipliant les deux lignes","En soustrayant"]'::jsonb, 0, 'Il doit être le même pour toutes les colonnes.', 4),
    ('aaa8c2f8-3da7-5a98-b9d1-18ec70e572af'::uuid, '871bb1a6-ec94-5ed9-974d-28d0b3b30b82'::uuid, 'Que représente 1 cm sur un plan à l’échelle 1/100 ?', 'mcq', '["1 m en réalité","100 m en réalité","10 cm en réalité","1 cm en réalité"]'::jsonb, 0, '1 cm × 100 = 100 cm = 1 m.', 5),
    ('b54061ca-a5c9-56f8-9d9a-4fee8a6b6aba'::uuid, '871bb1a6-ec94-5ed9-974d-28d0b3b30b82'::uuid, 'Qu’est-ce que la méthode du produit en croix ?', 'mcq', '["Dans a/b = c/d, on utilise a × d = b × c","On additionne les diagonales","On divise chaque terme par 2","On multiplie les lignes entre elles"]'::jsonb, 0, 'Elle sert à trouver une quatrième proportionnelle.', 6),
    ('938807bd-adab-5131-a15a-de2d2d20d89a'::uuid, '871bb1a6-ec94-5ed9-974d-28d0b3b30b82'::uuid, 'Comment reconnaît-on un tableau de proportionnalité ?', 'mcq', '["Toutes les colonnes donnent le même quotient","Les nombres augmentent","Il a deux lignes","La première ligne commence à 1"]'::jsonb, 0, 'C’est le test décisif.', 7),
    ('52aaa589-b880-517f-9169-3e0b35cb7c22'::uuid, '871bb1a6-ec94-5ed9-974d-28d0b3b30b82'::uuid, 'Un tarif avec abonnement fixe plus un prix à l’unité est proportionnel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’abonnement casse la proportionnalité : 0 unité ne coûte pas 0 €.', 8),
    ('cadc9de6-d9dd-57d5-a36b-c45d4583b583'::uuid, '56931cc4-b54f-5490-a895-8c3a62c5c4d0'::uuid, 'Comment calcule-t-on une fréquence ?', 'mcq', '["Effectif ÷ effectif total","Effectif × effectif total","Effectif total ÷ effectif","Effectif + effectif total"]'::jsonb, 0, 'Elle s’exprime souvent en pourcentage.', 1),
    ('2d2fc9f9-c51f-58fd-80ef-26267a03664a'::uuid, '56931cc4-b54f-5490-a895-8c3a62c5c4d0'::uuid, 'Quelle est la moyenne de 12, 15, 9 et 16 ?', 'mcq', '["13","12","14","52"]'::jsonb, 0, '52 ÷ 4.', 2),
    ('d13cfcf0-7257-5da4-b990-5f8ddad8c622'::uuid, '56931cc4-b54f-5490-a895-8c3a62c5c4d0'::uuid, 'Quel angle occupe une catégorie représentant 25 % dans un diagramme circulaire ?', 'mcq', '["90°","25°","180°","45°"]'::jsonb, 0, '0,25 × 360°.', 3),
    ('9ac8974e-15a1-550c-a6ee-e38199ac1230'::uuid, '56931cc4-b54f-5490-a895-8c3a62c5c4d0'::uuid, 'Quel diagramme convient le mieux pour montrer des parts d’un tout ?', 'mcq', '["Le diagramme circulaire","Le diagramme en barres","Le graphique cartésien","Le tableau"]'::jsonb, 0, 'Les barres servent surtout à comparer.', 4),
    ('f482e0b9-9eff-5f72-9f45-cd17272c0042'::uuid, '56931cc4-b54f-5490-a895-8c3a62c5c4d0'::uuid, 'Comment appelle-t-on l’ensemble étudié en statistiques ?', 'mcq', '["La population","Le caractère","L’effectif","La fréquence"]'::jsonb, 0, 'Le caractère est ce qu’on observe.', 5),
    ('80ebaf50-367f-5120-9db8-b12a438a1598'::uuid, '56931cc4-b54f-5490-a895-8c3a62c5c4d0'::uuid, 'Que faut-il vérifier en lisant un graphique ?', 'mcq', '["Le titre, les axes, les unités et l’origine de l’échelle","Seulement les couleurs","Seulement la hauteur des barres","Rien de particulier"]'::jsonb, 0, 'Un axe qui ne part pas de zéro exagère les écarts.', 6),
    ('ad96effe-e7a9-531a-8f09-db324754ad67'::uuid, '56931cc4-b54f-5490-a895-8c3a62c5c4d0'::uuid, 'Que vaut la somme des angles d’un diagramme circulaire ?', 'mcq', '["360°","180°","100°","90°"]'::jsonb, 0, 'Le disque entier représente l’effectif total.', 7),
    ('33721024-f959-5db1-a575-371dba679935'::uuid, '56931cc4-b54f-5490-a895-8c3a62c5c4d0'::uuid, 'Deux séries de même moyenne ont forcément des valeurs semblables.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La moyenne ne dit rien de la dispersion.', 8),
    ('c1ea4789-a33b-51ac-bd88-39d6d79fb20d'::uuid, '0e31b54c-5968-5f1d-a035-60a6d6eb185a'::uuid, 'Entre quelles valeurs une probabilité est-elle comprise ?', 'mcq', '["Entre 0 et 1","Entre 0 et 100","Entre −1 et 1","Entre 1 et 10"]'::jsonb, 0, '0 = impossible, 1 = certain.', 1),
    ('8034307b-6385-5e72-a9ee-8be92af8a94c'::uuid, '0e31b54c-5968-5f1d-a035-60a6d6eb185a'::uuid, 'Quelle est la probabilité d’obtenir 4 avec un dé à 6 faces ?', 'mcq', '["1/6","1/4","4/6","1/2"]'::jsonb, 0, 'Un cas favorable sur six possibles.', 2),
    ('12088239-8507-50c4-8ae6-e44454ac5052'::uuid, '0e31b54c-5968-5f1d-a035-60a6d6eb185a'::uuid, 'Quelle est la probabilité d’obtenir un nombre pair avec un dé à 6 faces ?', 'mcq', '["1/2","1/3","1/6","2/3"]'::jsonb, 0, '3 cas favorables sur 6.', 3),
    ('d59bb608-1b54-5e5a-b5a9-17e597bda70f'::uuid, '0e31b54c-5968-5f1d-a035-60a6d6eb185a'::uuid, 'Que vaut la probabilité d’un événement impossible ?', 'mcq', '["0","1","0,5","−1"]'::jsonb, 0, 'Un événement certain vaut 1.', 4),
    ('647cfded-ec26-5238-b73a-c484dd587d84'::uuid, '0e31b54c-5968-5f1d-a035-60a6d6eb185a'::uuid, 'Comment calcule-t-on une probabilité dans un cas équiprobable ?', 'mcq', '["Cas favorables ÷ cas possibles","Cas possibles ÷ cas favorables","Cas favorables × cas possibles","Cas favorables + cas possibles"]'::jsonb, 0, 'Toutes les issues doivent avoir la même chance.', 5),
    ('2b3bd628-0288-55bc-b9e1-993041f3a5b6'::uuid, '0e31b54c-5968-5f1d-a035-60a6d6eb185a'::uuid, 'Que vaut la somme des probabilités de deux événements contraires ?', 'mcq', '["1","0","0,5","2"]'::jsonb, 0, 'L’un se produit exactement quand l’autre ne se produit pas.', 6),
    ('c43d41ad-c44f-537c-838b-4e07cccdaad2'::uuid, '0e31b54c-5968-5f1d-a035-60a6d6eb185a'::uuid, 'Qu’est-ce qu’une expérience aléatoire ?', 'mcq', '["Une expérience dont on ne peut pas prévoir le résultat","Une expérience truquée","Une expérience répétée","Une expérience impossible"]'::jsonb, 0, 'Lancer un dé en est une.', 7),
    ('76ad02d3-ca34-54f4-a531-57e8991776be'::uuid, '0e31b54c-5968-5f1d-a035-60a6d6eb185a'::uuid, 'Après cinq « pile » d’affilée, « face » devient plus probable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La pièce n’a pas de mémoire : la probabilité reste 1/2.', 8),
    ('491ed05b-5a18-5fac-af31-88f0a372ace5'::uuid, '0cb5a637-af6b-53c9-97a2-f1a2d3507b30'::uuid, 'Qu’est-ce qu’un algorithme ?', 'mcq', '["Une suite finie et ordonnée d’instructions pour résoudre un problème","Un langage de programmation","Un ordinateur","Une erreur de programme"]'::jsonb, 0, 'Une recette de cuisine en est un.', 1),
    ('448338f6-6110-563f-b59d-bd197852a09d'::uuid, '0cb5a637-af6b-53c9-97a2-f1a2d3507b30'::uuid, 'À quoi sert une boucle ?', 'mcq', '["À répéter des instructions sans les réécrire","À arrêter le programme","À poser une question","À stocker une valeur"]'::jsonb, 0, 'Elle rend aussi le programme plus facile à corriger.', 2),
    ('9e8e4071-feb4-5e36-bcc6-d11aa3a4e2f6'::uuid, '0cb5a637-af6b-53c9-97a2-f1a2d3507b30'::uuid, 'Comment tracer un carré avec une boucle ?', 'mcq', '["Répéter 4 fois : avancer, tourner de 90°","Répéter 2 fois : avancer, tourner de 180°","Avancer 4 fois seulement","Répéter 4 fois : avancer de 90"]'::jsonb, 0, 'Pour un polygone à n côtés, on tourne de 360 ÷ n.', 3),
    ('5fa685ac-7e5a-50a3-8ddc-97100e78b9e2'::uuid, '0cb5a637-af6b-53c9-97a2-f1a2d3507b30'::uuid, 'Qu’est-ce qu’une variable ?', 'mcq', '["Une case mémoire nommée qui retient une valeur","Une instruction de déplacement","Une boucle","Un bug"]'::jsonb, 0, 'Un score ou un compteur en sont.', 4),
    ('3244bf9e-4fe4-52ab-8a8c-fe831b1425cb'::uuid, '0cb5a637-af6b-53c9-97a2-f1a2d3507b30'::uuid, 'Dans un repère, quelle coordonnée se lit en premier ?', 'mcq', '["L’abscisse, c’est-à-dire l’horizontale","L’ordonnée","La plus grande","Peu importe"]'::jsonb, 0, 'L’ordre ne s’invente pas.', 5),
    ('2bf31638-0290-5249-b3c2-938ab442e025'::uuid, '0cb5a637-af6b-53c9-97a2-f1a2d3507b30'::uuid, 'À quoi sert l’instruction « si … alors … sinon … » ?', 'mcq', '["À faire choisir le programme selon une condition","À répéter des instructions","À arrêter le programme","À nommer une variable"]'::jsonb, 0, '« Si le lutin touche le bord, alors rebondir ».', 6),
    ('b5a0db06-cd6b-5c87-b1e4-81713bf129bd'::uuid, '0cb5a637-af6b-53c9-97a2-f1a2d3507b30'::uuid, 'Qu’est-ce que déboguer un programme ?', 'mcq', '["Chercher et corriger les erreurs en testant pas à pas","L’effacer","Le rendre plus long","Le traduire"]'::jsonb, 0, 'Un programme se met au point.', 7),
    ('44978b96-f84b-553c-a75b-51bf5fbeaa4b'::uuid, '0cb5a637-af6b-53c9-97a2-f1a2d3507b30'::uuid, 'Une instruction d’algorithme peut rester un peu vague : la machine devinera.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une machine ne devine pas : chaque instruction doit être sans ambiguïté.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('maths');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('maths')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 329 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 329 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
